import {setup,load,esc,money,person,companyMark,link,button,pill,card,table,metric,head,downloadCSV} from './domain-ui.js?v=separate-2';
import {CRM_KEY,CRM_SEED} from './crm-data.js';
const ui=setup(),state=load(CRM_KEY,CRM_SEED),page=document.body.dataset.page,params=new URLSearchParams(location.search);
const field=(name,label,value='',options)=>({name,label,value,options});
const matches=v=>String(v).toLowerCase().includes(ui.search.value.toLowerCase().trim());
const save=message=>{ui.save(CRM_KEY,state,message);render();};
const companyURL=name=>'crm-companies.html?company='+encodeURIComponent(name);
function contacts(){return head('CRM / Relationships','Contacts','People involved in your sales opportunities.',button('Add contact','contact'))+card('Sales contacts',table(['Contact','Company','Role','Status','Action'],state.contacts.filter(c=>matches(c.name+' '+c.email+' '+c.company)).map(c=>`<tr><td>${person(c.name,c.email)}</td><td>${link(c.company,companyURL(c.company))}</td><td>${esc(c.role)}</td><td>${pill(c.status,c.status==='Customer'?'ok':'')}</td><td>${button('Edit contact','contact',c.id)}</td></tr>`)));}
function companies(){const names=[...new Set([...state.companies.map(c=>c.name),...state.deals.map(d=>d.name),...state.contacts.map(c=>c.company)])];const selected=params.get('company');if(selected&&names.includes(selected)){const company=state.companies.find(c=>c.name===selected),deals=state.deals.filter(d=>d.name===selected);return head('CRM / Companies',selected,company?.industry||'Sales account',button('Edit company','company',selected))+`<div class="app-metrics">${metric('Opportunities',deals.length,'Associated deals')}${metric('Pipeline value',money(deals.filter(d=>d.stage!=='Won').reduce((n,d)=>n+d.value,0)),'Open opportunities')}${metric('Contacts',state.contacts.filter(c=>c.company===selected).length,'People at this company')}</div>`+card('Account owner',person(company?.owner||deals[0]?.owner||'Unassigned'))+card('Associated opportunities',table(['Opportunity','Stage','Value','Next action'],deals.map(d=>`<tr><td>${link(d.name,'crm.html?deal='+encodeURIComponent(d.id))}</td><td>${pill(d.stage)}</td><td>${money(d.value)}</td><td>${esc(d.nextStep||'Not scheduled')}</td></tr>`)))+card('People',state.contacts.filter(c=>c.company===selected).map(c=>`<div class="account-security">${person(c.name,c.role)}${button('Edit contact','contact',c.id)}</div>`).join('')||'<p>No contacts yet. Add one from Contacts.</p>');}
return head('CRM / Accounts','Companies','Account relationships and their open opportunities.',button('Add company','company'))+`<div class="app-grid">${names.filter(matches).map(name=>{const c=state.companies.find(c=>c.name===name),deals=state.deals.filter(d=>d.name===name);return card(name,`<span class="person">${companyMark(name)}<span>${esc(c?.industry||'Sales account')}</span></span><p>${deals.length} opportunities · ${money(deals.reduce((n,d)=>n+d.value,0))}</p><p>${person(c?.owner||deals[0]?.owner||'Unassigned')}</p>${link('Open company →',companyURL(name))}`);}).join('')}</div>`;}
function activity(){return head('CRM / Follow-ups','Tasks & activity','Plan sales follow-ups and record completed work.',button('Add task','task'))+`<div class="app-columns">${card('Sales tasks',table(['Task','Company','Owner','Due','Status'],state.tasks.filter(t=>matches(t.title+' '+t.company+' '+t.owner)).map(t=>`<tr><td>${button(t.title,'task',t.id)}</td><td>${link(t.company,companyURL(t.company))}</td><td>${person(t.owner)}</td><td>${esc(t.due)}</td><td><label class="task-check"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''}>${t.done?'Complete':'Open'}</label></td></tr>`)))}${card('Sales activity',`<ul class="app-list">${state.activity.slice(0,15).map(t=>`<li>${esc(t)}</li>`).join('')||'<li>Complete a task or update a deal to record activity.</li>'}</ul>`)}</div>`;}
let selectedOwner='All owners';
function reports(){const owners=[...new Set(state.deals.map(d=>d.owner))],deals=state.deals.filter(d=>(selectedOwner==='All owners'||d.owner===selectedOwner)&&matches(d.name+' '+d.owner));const won=deals.filter(d=>d.stage==='Won').reduce((n,d)=>n+d.value,0);return head('CRM / Performance','Sales reports','Pipeline and won revenue derived from your CRM deals.',button('Export sales CSV','export'))+`<label class="demo-filter">Owner<select id="report-owner">${['All owners',...owners].map(o=>`<option ${o===selectedOwner?'selected':''}>${esc(o)}</option>`).join('')}</select></label><div class="app-metrics">${metric('Open pipeline',money(deals.filter(d=>d.stage!=='Won').reduce((n,d)=>n+d.value,0)),'Filtered opportunities')}${metric('Won revenue',money(won),'Closed won deals')}${metric('Sales target',money(state.salesSettings.target),'Configured in Sales settings')}${metric('Attainment',Math.round(won/Math.max(1,state.salesSettings.target)*100)+'%','Won revenue / target')}</div>`+card('Pipeline by stage',table(['Stage','Opportunities','Value'],['Lead','Qualified','Proposal','Won'].map(stage=>{const rows=deals.filter(d=>d.stage===stage);return `<tr><td>${pill(stage,stage==='Won'?'ok':'')}</td><td>${rows.length}</td><td>${money(rows.reduce((n,d)=>n+d.value,0))}</td></tr>`;})))+card('Opportunity detail',table(['Company','Owner','Stage','Value'],deals.map(d=>`<tr><td>${link(d.name,companyURL(d.name))}</td><td>${person(d.owner)}</td><td>${esc(d.stage)}</td><td>${money(d.value)}</td></tr>`)));}
function settings(){ui.search.closest('label').hidden=true;return head('CRM / Configuration','Sales settings','Defaults used only by the CRM application.')+card('Sales team',`<form class="app-form" id="sales-settings"><label>Team name<input name="team" required maxlength="100" value="${esc(state.salesSettings.team)}"></label><label>Default deal owner<input name="owner" required maxlength="100" value="${esc(state.salesSettings.owner)}"></label><label>Revenue target (USD)<input name="target" type="number" min="1" max="1000000000" required value="${state.salesSettings.target}"></label><button class="btn" type="submit">Save sales settings</button></form><p>The default owner is used for new deals. The target appears in Sales reports.</p>`);}
function render(){document.body.dataset.workspaceName=state.salesSettings.team;const label=document.querySelector('.suite-context [data-workspace-name]');if(label)label.textContent=state.salesSettings.team;ui.content.innerHTML=({contacts,companies,activity,reports,settings})[page]();}
ui.search.addEventListener('input',render);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;
 if(b.dataset.action==='contact'){const c=state.contacts.find(c=>c.id===id);ui.edit(c?'Edit contact':'Add contact',[field('name','Full name',c?.name),{...field('email','Email',c?.email),type:'email'},field('company','Company',c?.company),field('role','Role',c?.role),field('status','Status',c?.status||'New',['New','Qualified','Customer'])],v=>{if(c)Object.assign(c,v);else state.contacts.push({id:crypto.randomUUID(),...v});state.activity.unshift(`Updated contact ${v.name}.`);save('Contact saved in CRM.');});}
 if(b.dataset.action==='company'){const c=state.companies.find(c=>c.name===id);ui.edit(c?'Edit company':'Add company',[field('name','Company name',c?.name||id),field('industry','Industry',c?.industry),field('owner','Account owner',c?.owner||state.salesSettings.owner)],v=>{if(state.companies.some(x=>x!==c&&x.name===v.name)){ui.say('A company with that name already exists.');return;}if(c){const old=c.name;Object.assign(c,v);for(const d of state.deals)if(d.name===old)d.name=v.name;for(const person of state.contacts)if(person.company===old)person.company=v.name;for(const task of state.tasks)if(task.company===old)task.company=v.name;if(params.has('company')){params.set('company',v.name);history.replaceState(null,'','?'+params);}}else state.companies.push({...v,website:''});save('Company saved in CRM.');});}
 if(b.dataset.action==='task'){const t=state.tasks.find(t=>t.id===id);ui.edit(t?'Edit task':'Add task',[field('title','Task',t?.title),field('company','Company',t?.company),field('owner','Owner',t?.owner||state.salesSettings.owner),{...field('due','Due date',t?.due),type:'date'}],v=>{if(t)Object.assign(t,v);else state.tasks.push({id:crypto.randomUUID(),...v,done:false});save('Sales task saved.');});}
 if(b.dataset.action==='export'){downloadCSV('crm-sales.csv',[['Company','Owner','Stage','Value USD'],...state.deals.filter(d=>(selectedOwner==='All owners'||d.owner===selectedOwner)&&matches(d.name+' '+d.owner)).map(d=>[d.name,d.owner,d.stage,d.value])]);ui.say('Sales CSV downloaded.');}
});
ui.content.addEventListener('change',e=>{if(e.target.id==='report-owner'){selectedOwner=e.target.value;render();ui.content.querySelector('#report-owner').focus();}if(e.target.matches('[data-task]')){const t=state.tasks.find(t=>t.id===e.target.dataset.task);t.done=e.target.checked;state.activity.unshift(`${t.done?'Completed':'Reopened'}: ${t.title}`);save('Task updated.');ui.content.querySelector(`[data-task="${t.id}"]`).focus();}});
ui.content.addEventListener('submit',e=>{if(e.target.id!=='sales-settings')return;e.preventDefault();const v=Object.fromEntries(new FormData(e.target));state.salesSettings={team:v.team.trim(),owner:v.owner.trim(),target:Number(v.target)};save('Sales settings saved. Analytics settings are separate.');});
render();
